arguments.command:
cd /workspace && cat > /workspace/dev/bisect.py <<'EOF'
import sys, json, copy
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/project')
import ref, harness, fuzz
case=json.load(open(sys.argv[1]))
def mism(c):
    w=ref.run(c); g=harness.solve([c])['cases'][0]
    d=[]; fuzz.diff('x',g,w,d)
    return d
cur=copy.deepcopy(case)
d=mism(cur)
assert d, "no mismatch"
changed=True
while changed:
    changed=False
    i=0
    while i < len(cur['events']):
        trial=copy.deepcopy(cur); del trial['events'][i]
        if mism(trial):
            cur=trial; changed=True
        else:
            i+=1
    # try shrinking scalar fields
    for field,opts in [('capacity',[1,2,3]),('segments',None),('words',[1]),('trace',[0])]:
        if field=='segments':
            for k in range(1, cur['segments']+1):
                if cur['primitive']=='reducescatter' and k%4: continue
                if cur['primitive']=='barrier' and k!=1: continue
                trial=copy.deepcopy(cur); trial['segments']=k
                # drop events referencing p>=k
                ok=True
                for ev in trial['events']:
                    if ev['op'] in ('data','train'):
                        if ev['p']>=k: ok=False
                        if ev['op']=='train' and ev['p']+ev['count']>k: ok=False
                if ok and mism(trial):
                    cur=trial; break
        else:
            for v in opts:
                trial=copy.deepcopy(cur); trial[field]=v
                if field=='capacity':
                    for ev in trial['events']:
                        if ev['op']=='train' and ev['width']>v: ev['width']=v
                if mism(trial):
                    cur=trial; break
print(json.dumps(cur, indent=1))
print('DIFFS:')
for p,g,w in mism(cur)[:20]: print('  ',p,'got=',str(g)[:200],'want=',str(w)[:200])
json.dump(cur, open('/workspace/tmp/min.json','w'), indent=1)
EOF
timeout -s KILL 170 python3 -u dev/bisect.py /workspace/tmp/bad_1_48.json 2>&1 | tail -60
